import { Link } from "react-router-dom";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { ChevronRight, FlaskConical, Database, RefreshCw, Loader2, AlertCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useAIPipelineRows, useCompanyLiveStats } from "@/hooks/useCompanyLiveData";

export default function AIResearchLab() {
  const { data: pipelines, isLoading, refetch, isFetching } = useAIPipelineRows();
  const { data: stats } = useCompanyLiveStats();

  return (
    <div className="container mx-auto px-4 py-8 max-w-6xl">
      <div className="mb-6 flex items-center gap-2 text-xs text-muted-foreground">
        <Link to="/hub" className="hover:text-cyan-400">Platform Hub</Link>
        <ChevronRight className="h-3 w-3" />
        <Link to="/company/ai-research" className="hover:text-cyan-400">AI Research</Link>
        <ChevronRight className="h-3 w-3" />
        <span className="text-fuchsia-400">Model Training Lab</span>
      </div>

      <div className="flex items-start justify-between gap-4 mb-8">
        <div className="flex items-start gap-4">
          <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-gradient-to-br from-fuchsia-500 to-pink-600">
            <FlaskConical className="h-6 w-6 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold">AI Pipeline Monitor</h1>
            <p className="text-sm text-muted-foreground mt-1">
              Live edge-function metrics from <code className="text-xs">function_metrics</code> — no simulated models
            </p>
          </div>
        </div>
        <Button variant="outline" size="sm" onClick={() => refetch()} disabled={isFetching}>
          {isFetching ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
        </Button>
      </div>

      <div className="grid gap-4 sm:grid-cols-3 mb-8">
        <Card>
          <CardContent className="pt-5 flex items-center gap-3">
            <Database className="h-8 w-8 text-fuchsia-400/70" />
            <div>
              <p className="text-2xl font-bold tabular-nums">{stats?.aiSummarizedItems?.toLocaleString() ?? "—"}</p>
              <p className="text-xs text-muted-foreground">Items with AI summary (DB)</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-5 flex items-center gap-3">
            <FlaskConical className="h-8 w-8 text-fuchsia-400/70" />
            <div>
              <p className="text-2xl font-bold tabular-nums">{pipelines?.length ?? "—"}</p>
              <p className="text-xs text-muted-foreground">AI functions with metrics</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-5 flex items-center gap-3">
            <Database className="h-8 w-8 text-fuchsia-400/70" />
            <div>
              <p className="text-2xl font-bold tabular-nums">
                {stats?.pipelineSuccessRate != null ? `${stats.pipelineSuccessRate}%` : "—"}
              </p>
              <p className="text-xs text-muted-foreground">Recent pipeline success</p>
            </div>
          </CardContent>
        </Card>
      </div>

      {isLoading ? (
        <p className="text-sm text-muted-foreground animate-pulse">Loading function_metrics…</p>
      ) : !pipelines?.length ? (
        <Card className="border-dashed">
          <CardContent className="py-10 text-center text-sm text-muted-foreground">
            <AlertCircle className="h-8 w-8 mx-auto mb-3 text-amber-400" />
            No AI pipeline metrics in database yet. Metrics appear after edge functions run (ai-brief, ai-live-intel, ai-fusion, etc.).
          </CardContent>
        </Card>
      ) : (
        <div className="grid gap-4 md:grid-cols-2">
          {pipelines.map((p) => (
            <Card key={p.functionName}>
              <CardHeader className="pb-2 flex flex-row items-start justify-between">
                <CardTitle className="text-base font-mono">{p.functionName}</CardTitle>
                <Badge variant="outline" className={p.successPct >= 90 ? "border-emerald-500/30 text-emerald-400" : "border-amber-500/30 text-amber-400"}>
                  {p.successPct}% success
                </Badge>
              </CardHeader>
              <CardContent className="text-sm space-y-1 text-muted-foreground">
                <p><span className="text-slate-500">Invocations:</span> {p.calls}</p>
                <p><span className="text-slate-500">Avg duration:</span> {p.avgMs} ms</p>
                <p><span className="text-slate-500">Items processed:</span> {p.itemsProcessed.toLocaleString()}</p>
                <p><span className="text-slate-500">Last run:</span> {new Date(p.lastRun).toLocaleString()}</p>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}
